it('">a..b" / "a..<b" are silently rewritten with the opposite uncertainty direction', () => {
  const a = parseLocation('>5..10', 20, 'linear');
  const b = parseLocation('1..<9', 20, 'linear');
  if (!a.ok || !b.ok) throw new Error('parse failed');
  const fa = formatLocation(a, 20, 'linear');
  const fb = formatLocation(b, 20, 'linear');
  expect(fa === '>5..10' || a.warnings.length > 0).toBe(true); // got '<5..10', no warning
  expect(fb === '1..<9' || b.warnings.length > 0).toBe(true); // got '1..>9', no warning
