  const text = [
    LOCUS,
    'FEATURES             Location/Qualifiers',
    '     gene            1..4',
    '                     /gene="abc"',
    'stray text',
    '     gene            5..8',
    '                     /gene="def"',
    '     CDS             9..12',
    '                     /gene="ghi"',
    'ORIGIN',
    '        1 acgtacgtac gt',
