  ].join('\n');
  const r = parseGenbank(text);
  // Biopython 1.88: 3 features + "line too short to contain a feature: 'stray text'"
  expect(r.records[0].features.map((f) => f.name)).toEqual(['abc', 'def', 'ghi']);
});

