const LOCUS = 'LOCUS       test                      12 bp    DNA     linear   SYN 01-JAN-2020';

it('F3: an ORGANISM sub-keyword indented by 4 blanks is not swallowed into SOURCE', () => {
  const r = parseGenbank(
    [
      LOCUS,
      'SOURCE      Escherichia coli',
      '    ORGANISM  Escherichia coli',
      '            Bacteria; Pseudomonadota; Gammaproteobacteria.',
      'ORIGIN',
      '        1 acgtacgtac gt',
      '//',
    ].join('\n'),
  );
  const meta = r.records[0].meta;
  // Biopython 1.88: source 'Escherichia coli', organism 'Escherichia coli', taxonomy [Bacteria, ...]
  expect(meta.source).toBe('Escherichia coli');
  expect(meta.organism).toBe('Escherichia coli');
});

